SELECT 
  (SELECT A11 FROM district WHERE district_id = (
    SELECT district_id FROM client WHERE gender = 'F' ORDER BY birth_date ASC LIMIT 1
  )) AS lowest_avg_salary,
  (SELECT MAX(A11) FROM district WHERE district_id IN (
    SELECT district_id FROM client WHERE gender = 'F'
  )) AS highest_avg_salary,
  (SELECT MAX(A11) FROM district WHERE district_id IN (
    SELECT district_id FROM client WHERE gender = 'F'
  )) - (SELECT A11 FROM district WHERE district_id = (
    SELECT district_id FROM client WHERE gender = 'F' ORDER BY birth_date ASC LIMIT 1
  )) AS gap
